public class RandomStringUtils_random_TriageGen1Test {







    @Test
    public void testRandom_CharsProvided() {
        char[] chars = {'a', 'b', 'c'};
        // start=0, end=3, gap=3
        String result = RandomStringUtils.random(5, 0, 3, false, false, chars, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'a' || c == 'b' || c == 'c');
        }
    }












}

